mapper.select:
SELECT * FROM project
WHERE category = #{category}
ORDER BY date DESC

SELECT p.id, p.title, p.description, p.category, p.image_url, p.demo_url, p.github_url, p.date, p.created_at, t.id as tech_id, t.name as tech_name, t.category as tech_category, t.icon as tech_icon, t.created_at as tech_created_at, pt.sort_order FROM project p LEFT JOIN project_tech pt ON p.id = pt.project_id LEFT JOIN tech t ON pt.tech_id = t.id
AND p.title LIKE CONCAT('%', #{title}, '%')
AND p.category = #{category}
AND p.date >= #{startDate}
AND p.date <= #{endDate}
AND t.name = #{techName}
ORDER BY p.date DESC, pt.sort_order ASC
